"""Benchmark-local deadline and oracle hooks for the pinned tinygrad BEAM loop.

Does not edit upstream. Search buffers contain the actual F16 projection;
every timed candidate must overwrite a NaN sentinel and pass a float64 oracle.
"""
import hashlib,json,math,pickle,sqlite3,time
from dataclasses import replace
from pathlib import Path
import numpy as np
from tinygrad import dtypes
from tinygrad.helpers import Context,diskcache_put
from tinygrad.codegen import to_program
from tinygrad.codegen.opt import search


class SearchDeadline(KeyboardInterrupt):pass


class BudgetSearch:
    def __init__(self,seconds,out,x,weight,expected,tolerance,*,fallback_cache=None):
        self.seconds=seconds;self.out=Path(out);self.out.mkdir(parents=True,exist_ok=True)
        self.x=np.ascontiguousarray(x);self.weight=np.ascontiguousarray(weight)
        self.expected=expected;self.tolerance=tolerance;self.fallback_cache=fallback_cache
        self.stats={'budget_seconds':seconds,'compiled_attempts':0,'compile_failures':0,'passed':0,'rejected':0,'incumbents':[]}
        self.started=None;self.best=None;self.programs={};self.key=None

    def save(self):
        self.stats['elapsed_seconds']=time.perf_counter()-self.started
        if self.best is not None:
            schedule,seconds,program=self.best
            self.stats['best_gpu_seconds']=seconds
            self.stats['best_opts']=[str(v) for v in schedule.applied_opts]
            self.stats['best_source_sha256']=hashlib.sha256(program.src[2].arg.encode()).hexdigest()
            (self.out/'best-source.txt').write_text(program.src[2].arg)
            diskcache_put('beam_search',self.key,schedule.applied_opts)
        (self.out/'search-progress.json').write_text(json.dumps(self.stats,indent=2)+'\n')

    def deadline(self):
        if time.perf_counter()-self.started>=self.seconds:raise SearchDeadline()

    def compile(self,item):
        self.deadline();self.stats['compiled_attempts']+=1
        result=self.original_compile(item)
        if result[1] is not None:
            program=result[1][0];self.programs[program.src[3].arg]=item[1].copy()
        else:self.stats['compile_failures']+=1
        if self.stats['compiled_attempts']%25==0:self.save()
        return result

    def timed(self,program,var_vals,rawbufs,*args,**kwargs):
        self.deadline()
        sentinel=np.full(self.expected.size,np.nan,np.float32)
        rawbufs[0].allocator._copyin(rawbufs[0]._buf,memoryview(sentinel).cast('B'))
        times=self.original_time(program,var_vals,rawbufs,*args,**kwargs)
        actual=rawbufs[0].numpy().reshape(self.expected.shape)
        valid=np.all(np.isfinite(actual)) and np.all(np.abs(actual-self.expected)<=self.tolerance)
        self.stats['passed' if valid else 'rejected']+=1
        if not valid:
            self.save();return [math.inf]*len(times)
        score=min(times)
        if math.isfinite(score) and (self.best is None or score<self.best[1]):
            self.best=(self.programs[program.src[3].arg].copy(),score,program)
            self.stats['incumbents'].append({'elapsed_seconds':time.perf_counter()-self.started,'compiled_attempts':self.stats['compiled_attempts'],
                                             'gpu_seconds':score,'opts':[str(v) for v in self.best[0].applied_opts]})
            self.save()
            print('search incumbent',self.stats['compiled_attempts'],round(score*1e6,3),'us',flush=True)
        return times

    def beam(self,s,rawbufs,var_vals,amt,allow_test_size=True):
        if self.started is not None:raise RuntimeError('budget hook expects one projection kernel')
        if allow_test_size:raise ValueError('oracle requires full-shape search timing')
        self.started=time.perf_counter()
        self.key={'ast':s.ast.key,'amt':amt,'allow_test_size':allow_test_size,'device':s.ren.target.device,'suffix':s.ren.suffix}
        self.stats.update(ast_sha256=s.ast.key.hex(),beam_width=amt)
        expected_buffers=[(self.expected.size,dtypes.float),(self.x.size,dtypes.float),(self.weight.size,dtypes.half)]
        if [(b.size,b.dtype) for b in rawbufs]!=expected_buffers:raise ValueError('unsupported projection parameter order/dtypes')
        for buf in rawbufs:buf.ensure_allocated()
        for buf,array in zip(rawbufs[1:],(self.x,self.weight)):
            buf.allocator._copyin(buf._buf,memoryview(array).cast('B'))
        fallback=s.copy()
        if self.fallback_cache:
            with sqlite3.connect('file:'+str(Path(self.fallback_cache).resolve())+'?mode=ro',uri=True) as db:
                ast_key=s.ast.replace(arg=replace(s.ast.arg,beam=2)).key if hasattr(s.ast.arg,'beam') else s.ast.key
                row=db.execute('select val from beam_search_24 where ast=? and amt=2 and allow_test_size=0 and device=?',
                               (ast_key,s.ren.target.device)).fetchone()
            if row is None:raise ValueError(('missing validated fallback schedule',s.ast.arg,s.ast.key.hex(),ast_key.hex()))
            for opt in pickle.loads(row[0]):fallback.apply_opt(opt)
        else:
            from tinygrad.codegen.opt.heuristic import hand_coded_optimizations
            fallback=hand_coded_optimizations(fallback)
        program=to_program(fallback.get_optimized_ast(name_override='fallback'),s.ren)
        self.programs[program.src[3].arg]=fallback
        self.timed(program,var_vals,rawbufs,allow_test_size=False)
        if self.best is None:raise AssertionError('fallback failed the projection oracle')
        try:
            # Checkpoint cache entries must not short-circuit the running search.
            with Context(IGNORE_BEAM_CACHE=1):self.original_beam(s,rawbufs,var_vals,amt,False)
            self.stats['stop_reason']='converged'
        except SearchDeadline:self.stats['stop_reason']='time budget'
        self.save()
        print('search finished',self.stats,flush=True)
        return self.best[0].copy()

    def __enter__(self):
        self.original_compile,self.original_time,self.original_beam=search._try_compile,search._time_program,search.beam_search
        search._try_compile,search._time_program,search.beam_search=self.compile,self.timed,self.beam
        return self

    def __exit__(self,*exc):
        search._try_compile,search._time_program,search.beam_search=self.original_compile,self.original_time,self.original_beam

tinygrad_compare.py.source:
"""Matched LFM2 comparison against an experimental tinygrad adapter.

Upstream tinygrad does not implement LFM2. This uses its generic Tensor/JIT
compiler on the same checkpoint and precision contract, not custom AMD kernels.
"""
from pathlib import Path as _Path
import sys as _sys
_sys.path.insert(0,str(_Path(__file__).resolve().parents[2]))
import argparse,hashlib,json,os,statistics,subprocess,time
from pathlib import Path
import numpy as np
import tensor
from tensor_llm import LFM2
from benchmarks.lfm2.webgpu_run import cached_reference,metrics
from benchmarks.lfm2.vulkan_reference import Reference as NativeReference,COMMIT
from benchmarks.lfm2.tinygrad_reference import Reference as TinyReference


def tiny_info():
    import tinygrad
    from tinygrad import Device
    from tinygrad.helpers import CACHEDB
    device=Device[Device.DEFAULT]
    repository=Path(tinygrad.__file__).resolve().parents[1]
    result={'revision':subprocess.check_output(['git','-C',str(repository),'rev-parse','HEAD'],text=True).strip(),
            'device':Device.DEFAULT,'renderer':str(device.renderer.target),
            'beam':int(os.environ.get('BEAM','0')),'jitbeam':int(os.environ.get('JITBEAM',os.environ.get('BEAM','0'))),
            'cache':CACHEDB}
    result['search_controls']={name:os.environ[name] for name in ('BEAM_ESTIMATE','BEAM_UPCAST_MAX','BEAM_LOCAL_MAX','NOOPT') if name in os.environ}
    if Device.DEFAULT.startswith('CL'):
        result.update(name=device.device_name,driver=device.driver_version)
        if device.device_name!='gfx1031':raise RuntimeError('requires the recorded Radeon adapter')
    elif Device.DEFAULT.startswith('WEBGPU'):
        from tinygrad.runtime.ops_webgpu import webgpu,instance,InstanceRequestAdapter,backend_types,from_wgpu_str
        adapter=InstanceRequestAdapter(instance,webgpu.WGPURequestAdapterOptions(powerPreference=webgpu.WGPUPowerPreference_HighPerformance,
            backendType=backend_types.get(os.environ.get('WEBGPU_BACKEND',''),0)))
        info=webgpu.WGPUAdapterInfo();webgpu.wgpuAdapterGetInfo(adapter,info)
        result.update({name:from_wgpu_str(getattr(info,name)) for name in ('vendor','architecture','description')})
        result['name']=from_wgpu_str(info.device)
        result['backend']=webgpu.enum_WGPUBackendType[info.backendType]
        result['vendor_id']=info.vendorID;result['device_id']=info.deviceID
        webgpu.wgpuAdapterInfoFreeMembers(info);webgpu.wgpuAdapterRelease(adapter)
        if result['backend']!='WGPUBackendType_Vulkan' or result['vendor_id']!=4098 or result['device_id']!=29663:
            raise RuntimeError('requires physical RX 6700 XT Vulkan adapter')
    else:raise RuntimeError('comparison requires CL or Vulkan WEBGPU')
    return result


def check(name,actual,expected):
    result=metrics(actual,expected)
    if not np.all(np.isfinite(actual)) or result['relative_rms']>=.01 or result['cosine']<=.9999 or result['argmax'][0]!=result['argmax'][1]:
        raise AssertionError((name,result))
    return result


def run(model,bundle,reference,fixtures,out,*,repeats=5,decode=64,weight_mode='packed',validation_only=False):
    out=Path(out);out.mkdir(parents=True,exist_ok=True)
    cases=[{key:case[key] for key in ('name','tokens','reset')} for case in json.loads((Path(fixtures)/'report.json').read_text())['validation']]
    expected,oracle=cached_reference(fixtures,model,cases)
    start=time.perf_counter();tiny=TinyReference(model,weight_mode=weight_mode);load=time.perf_counter()-start
    info=tiny_info();print('tinygrad',info,'load seconds',load,flush=True)
    native=NativeReference(model,reference,context=512)
    try:
        with tensor.Device(provider='webgpu') as device,LFM2(model,bundle,device,context=512) as engine:
            if device.info['adapter']['backend_type']!='Vulkan':raise RuntimeError('requires Vulkan')
            first_calls={};prompt=cases[0]['tokens'];runners={'tensor':engine,'tinygrad':tiny,'llama_cpp':native}
            for name,runner in runners.items():
                runner.reset();start=time.perf_counter();actual=runner.forward(prompt);elapsed=time.perf_counter()-start
                comparison=metrics(actual,expected[0]) if name=='llama_cpp' else check('first_'+name,actual,expected[0])
                first_calls[name]={'seconds':elapsed,'numpy':comparison}
                print('first_call',name,elapsed,flush=True)
            validation=[];first={}
            for i,case in enumerate(cases):
                row={**case,'completed_seconds':{}}
                for name,runner in runners.items():
                    if case['reset']:runner.reset()
                    start=time.perf_counter();actual=runner.forward(case['tokens'])
                    row['completed_seconds'][name]=time.perf_counter()-start
                    np.save(out/f'{i}-{name}-logits.npy',actual)
                    try:
                        row[name]=metrics(actual,expected[i]) if name=='llama_cpp' else check(case['name']+'_'+name,actual,expected[i])
                    except AssertionError:
                        failure={'status':'failed','model':str(Path(model).resolve()),'model_sha256':oracle['model_sha256'],
                                 'tinygrad':info,'first_call':first_calls,'independent_reference':oracle,
                                 'validation':validation,'failed_fixture':{**row,'runner':name,'metrics':metrics(actual,expected[i])}}
                        (out/'report.json').write_text(json.dumps(failure,indent=2)+'\n')
                        raise
                    if i==0:first[name]=actual.copy()
                    if case['name']=='reset_chat' and not np.array_equal(first[name],actual):raise AssertionError('reset must be bitwise identical: '+name)
                validation.append(row);print('validation',case['name'],row['tinygrad'],flush=True)
            benchmarks=[];forced=np.resize(prompt,decode).tolist()
            report={'status':'measuring','model':str(Path(model).resolve()),'model_sha256':oracle['model_sha256'],
                    'tinygrad':info,'tinygrad_adapter_sha256':hashlib.sha256(Path(__file__).with_name('tinygrad_reference.py').read_bytes()).hexdigest(),
                    'weight_mode':weight_mode,'weight_storage':{'f16_gguf':'native FP16','f32_gguf':'native FP32'},
                    'adapter':device.info,'implementation':engine.manifest['implementation'],
                    'native_commit':COMMIT,'independent_reference':oracle,'loading_seconds':{'tinygrad':load},
                    'first_call':first_calls,'validation':validation,'benchmarks':benchmarks,
                    'protocol':{'context':512,'prefill_chunk':32,'warmups':3,'repeats':repeats,'host_logits':'FP32','sampling':'excluded',
                                'loading':'excluded from warmed timings','order':'rotate all three runners, sequential GPU execution',
                                'first_call':'includes graph/kernel compilation where needed; isolated persistent tinygrad cache; Tensor producer AOT compilation excluded',
                                'tinygrad_attention':'fixed 576-entry FP16 KV buffers with causal mask; generic compiler, no upstream AMD LLM kernels'}}
            (out/'report.json').write_text(json.dumps(report,indent=2)+'\n')
            for length in (() if validation_only else (32,128,384)):
                prefix=np.resize(prompt,length).tolist();samples={name:[] for name in runners};names=list(runners)
                # Three warmups allow tinygrad's initial call and JIT capture
                # to complete before timing either static row profile.
                for repeat in range(repeats+3):
                    order=names[repeat%3:]+names[:repeat%3]
                    for name in order:
                        runner=runners[name];runner.reset();start=time.perf_counter();runner.forward(prefix);prefill=time.perf_counter()-start
                        start=time.perf_counter()
                        for token in forced:runner.forward([token])
                        elapsed=time.perf_counter()-start
                        if repeat>=3:samples[name].append({'prefill_seconds':prefill,'decode_seconds':elapsed})
                row={'prompt_tokens':length,'decode_tokens':decode,'samples':samples}
                for name,values in samples.items():
                    row[name]={'prefill_tokens_per_second':length/statistics.median(x['prefill_seconds'] for x in values),
                               'decode_tokens_per_second':decode/statistics.median(x['decode_seconds'] for x in values)}
                benchmarks.append(row);print('benchmark',length,{name:row[name] for name in names},flush=True)
                (out/'report.json').write_text(json.dumps(report,indent=2)+'\n')
            report['status']='passed'
            (out/'report.json').write_text(json.dumps(report,indent=2)+'\n')
    finally:native.close()


if __name__=='__main__':
    p=argparse.ArgumentParser(description=__doc__)
    for name in ('model','bundle','reference','fixtures','out'):p.add_argument('--'+name,required=True,type=Path)
    p.add_argument('--repeats',type=int,default=5);p.add_argument('--decode',type=int,default=64)
    p.add_argument('--weight-mode',choices=('packed','decoded'),default='packed')
    p.add_argument('--validation-only',action='store_true')
    a=p.parse_args()
    if a.repeats<1 or not 1<=a.decode<=128:p.error('requires positive repeats and 1..128 decode tokens')
    run(a.model,a.bundle,a.reference,a.fixtures,a.out,repeats=a.repeats,decode=a.decode,weight_mode=a.weight_mode,validation_only=a.validation_only)

tinygrad_reference.py.source:
"""Experimental LFM2 adapter for tinygrad's generic compiler, not its AMD LLM kernels.

Matches the existing NumPy precision contract. Fixed 1/32-row JITs use symbolic
position and valid-row count; short convolution state is reset inside the graph.
"""
import numpy as np
from tinygrad import Tensor,TinyJit,UOp,Device,dtypes
from tinygrad.llm.gguf import ggml_data_to_tensor
from tensor_llm.gguf import GGUF
from tensor_llm.config import Config


def rounded_half(value):
    """Explicit nearest-even half operands on the measured Dawn/Vulkan stack.

    Its native f16 conversion truncates; round in FP32 before an exact cast.
    The integer path covers normal halves and the scaled path subnormal halves.
    """
    if value.dtype==dtypes.half:return value.float()
    if not Device.DEFAULT.startswith('WEBGPU'):return value.half().float()
    value=value.float();bits=value.bitcast(dtypes.uint32);magnitude=value.abs()
    normal=((bits+4095+((bits>>13)&1))&0xffffe000).bitcast(dtypes.float)
    scaled=magnitude*16777216;lower=scaled.floor();fraction=scaled-lower
    increment=(fraction>.5)|((fraction==.5)&((lower.cast(dtypes.int32)&1)==1))
    small=(lower+increment.float())/16777216
    small=(small.bitcast(dtypes.uint32)|(bits&0x80000000)).bitcast(dtypes.float)
    result=(magnitude<2**-14).where(small,normal)
    infinity=(value<0).where(float('-inf'),float('inf'))
    return value.isnan().where(value,(magnitude>=65520).where(infinity,result))


class Reference:
    def __init__(self,path,*,context=512,weight_mode='packed'):
        self.gguf=GGUF(path);self.config=Config.from_gguf(self.gguf);self.context=context
        self.device=Device.DEFAULT;self.capacity=(context+32+63)//64*64
        self.weights={}
        for name,info in self.gguf.tensors.items():
            if info.type in (0,1):
                value=Tensor(np.array(self.gguf.array(name,dtype=np.float16 if info.type==1 else np.float32),copy=True),device=self.device).realize()
            elif weight_mode=='decoded':
                value=Tensor(np.array(self.gguf.array(name),copy=True),device=self.device).realize()
            else:
                raw=Tensor(np.array(self.gguf.packed(name),copy=True),device=self.device).realize()
                value=ggml_data_to_tensor(raw,int(np.prod(info.shape)),info.type).reshape(info.shape)
            self.weights[name]=value
        if any(self.weights[name].dtype!=dtypes.half for name,info in self.gguf.tensors.items() if info.type==1):
            raise ValueError('F16 GGUF tensors must retain native half storage')
        c=self.config
        self.states={i:Tensor.zeros(2,c.width,device=self.device).realize() for i,k in enumerate(c.layers) if k=='conv'}
        self.caches={i:tuple(Tensor.zeros(self.capacity,c.kv_heads,c.head_dim,dtype=dtypes.half,device=self.device).realize() for _ in range(2))
                     for i,k in enumerate(c.layers) if k=='attention'}
        angles=np.arange(self.capacity,dtype=np.float32)[:,None]*np.exp(np.arange(c.head_dim//2,dtype=np.float32)*np.float32(-np.log(c.theta)*2/c.head_dim))
        self.cos=Tensor(np.cos(angles),device=self.device).realize();self.sin=Tensor(np.sin(angles),device=self.device).realize()
        self.jits={r:TinyJit(self._chunk) for r in (1,32)}
        self.reset();Device[self.device].synchronize()

    def reset(self):self.position=0

    def _chunk(self,tokens,start,valid):
        c=self.config;r=tokens.shape[0];d=c.head_dim;w=self.weights
        def project(name,x,single=False):
            weight=w[name]
            if r>1 and not single:x,weight=rounded_half(x),rounded_half(weight)
            else:x,weight=x.float(),weight.float()
            return x@weight.T
        def norm(name,x):return x*(x.square().mean(axis=-1,keepdim=True)+c.epsilon).rsqrt()*w[name].float()
        def rotate(x):
            left,right=x.chunk(2,dim=-1)
            co=self.cos[start:start+r].reshape(r,1,d//2);si=self.sin[start:start+r].reshape(r,1,d//2)
            return (left*co-right*si).cat(left*si+right*co,dim=-1)
        hidden=w['token_embd.weight'][tokens].float()
        for i,kind in enumerate(c.layers):
            p=f'blk.{i}.';x=norm(p+'attn_norm.weight',hidden)
            if kind=='conv':
                b,gate,v=project(p+'shortconv.in_proj.weight',x).chunk(3,dim=-1)
                state=Tensor(start).eq(0).where(0,self.states[i])
                combined=state.cat(b*v,dim=0).contiguous()
                state_store=self.states[i].uop.store(combined[valid:valid+2].uop)
                filters=w[p+'shortconv.conv.weight'].float()
                conv=sum(combined[j:j+r]*filters[:,j] for j in range(3))*gate
                mix=project(p+'shortconv.out_proj.weight',conv)
                mix=Tensor(mix.contiguous().uop.after(state_store))
            else:
                q=project(p+'attn_q.weight',x).reshape(r,c.heads,d)
                k=project(p+'attn_k.weight',x).reshape(r,c.kv_heads,d)
                v=project(p+'attn_v.weight',x).reshape(r,c.kv_heads,d)
                q=rotate(norm(p+'attn_q_norm.weight',q));k=rotate(norm(p+'attn_k_norm.weight',k))
                kc,vc=self.caches[i]
                ks=kc[start:start+r].uop.store(rounded_half(k).half().uop);vs=vc[start:start+r].uop.store(rounded_half(v).half().uop)
                keys=Tensor(kc.uop.after(ks)).float().unsqueeze(2).expand(self.capacity,c.kv_heads,c.heads//c.kv_heads,d).reshape(self.capacity,c.heads,d).permute(1,0,2)
                vals=Tensor(vc.uop.after(vs)).float().unsqueeze(2).expand(self.capacity,c.kv_heads,c.heads//c.kv_heads,d).reshape(self.capacity,c.heads,d).permute(1,0,2)
                scores=(q.permute(1,0,2)@keys.transpose(-1,-2))*d**-0.5
                mask=Tensor.arange(self.capacity).to(self.device).reshape(1,1,self.capacity)>(Tensor.arange(r).to(self.device)+start).reshape(1,r,1)
                prob=mask.where(float('-inf'),scores).softmax(-1)
                attn=(prob@vals).permute(1,0,2).reshape(r,c.width)
                mix=project(p+'attn_output.weight',attn)
            hidden=hidden+mix;x=norm(p+'ffn_norm.weight',hidden)
            gate=project(p+'ffn_gate.weight',x);up=project(p+'ffn_up.weight',x)
            hidden=hidden+project(p+'ffn_down.weight',gate.silu()*up)
        final=norm('token_embd_norm.weight',hidden[valid-1:valid])
